import csv
import io
import re
from collections import Counter


def parse_csv(raw_csv: str):
    expected_width = 8
    stream = io.StringIO(raw_csv.removeprefix("\ufeff"), newline="")
    records = list(csv.reader(stream, delimiter=",", quotechar='"', doublequote=True))
    if not records:
        return {"columns": [], "rows": []}

    def filled(row):
        return sum(bool(value.strip()) for value in row)

    def is_label(value):
        value = value.strip()
        return bool(re.search(r"[^\W\d_]", value)) and not re.fullmatch(
            r"[+-]?\d+(?:[.,]\d+)*(?:[eE][+-]?\d+)?%?", value
        )

    header_index = next(
        (
            i for i, row in enumerate(records)
            if len(row) >= expected_width - 1
            and filled(row) >= expected_width // 2
            and sum(is_label(value) for value in row) > filled(row) // 2
        ),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(records) if filled(row) >= expected_width // 2),
            None,
        )

    width = max(expected_width, max(map(len, records)))

    def pad(row):
        return row + [""] * (width - len(row))

    if header_index is None:
        return {
            "columns": [f"column_{i + 1}" for i in range(width)],
            "rows": [pad(row) for row in records],
        }

    labels = [value.strip() for value in pad(records[header_index])]
    counts = Counter(labels)
    duplicate_positions = {
        i for i, label in enumerate(labels) if label and counts[label] > 1
    }

    def duplicate_context(row):
        positions = {i for i, value in enumerate(row) if value.strip()}
        return bool(positions) and positions <= duplicate_positions

    context = []
    if header_index > 0 and duplicate_context(records[header_index - 1]):
        context.append(records[header_index - 1])
    if header_index + 1 < len(records) and duplicate_context(records[header_index + 1]):
        context.append(records[header_index + 1])

    columns = []
    used = set()
    for i, label in enumerate(labels):
        base = label or f"column_{i + 1}"
        if i in duplicate_positions:
            qualifiers = [row[i].strip() for row in context if i < len(row) and row[i].strip()]
            if qualifiers:
                base = f"{base} ({', '.join(qualifiers)})"
        name = base
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used.add(name)

    return {
        "columns": columns,
        "rows": [pad(row) for i, row in enumerate(records) if i != header_index],
    }
